from collections import Counter


class DataStatistics:
    NEVEN_MODULO = 2

    def mean(self, data):
        return round(sum(data) / len(data), 2)

    def median(self, data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % self.NEVEN_MODULO == 0:
            return self._calculate_even_median(sorted_data, n)
        else:
            return self._calculate_odd_median(sorted_data, n)

    def _calculate_even_median(self, sorted_data, n):
        middle = n // 2
        return round((sorted_data[middle - 1] + sorted_data[middle]) / 2, 2)

    def _calculate_odd_median(self, sorted_data, n):
        middle = n // 2
        return sorted_data[middle]

    def mode(self, data):
        counter = Counter(data)
        mode_count = self._get_max_count(counter)
        mode_values = self._get_mode_values(counter, mode_count)
        return mode_values

    def _get_max_count(self, counter):
        return max(counter.values())

    def _get_mode_values(self, counter, mode_count):
        return [x for x, count in counter.items() if count == mode_count]
